WITH cust_store_year AS ( SELECT c.c_customer_sk, c.c_first_name, c.c_last_name, s.s_store_sk, s.s_store_name, d_sold.d_year AS sales_year, SUM(ws.ws_net_profit) AS total_profit, SUM(ws.ws_net_paid) AS total_paid, COUNT(*) AS order_cnt FROM web_sales ws JOIN customer c ON ws.ws_bill_customer_sk = c.c_customer_sk JOIN date_dim d_sold ON ws.ws_sold_date_sk = d_sold.d_date_sk JOIN store s ON ws.ws_warehouse_sk = s.s_store_sk LEFT JOIN date_dim cd_closed ON s.s_closed_date_sk = cd_closed.d_date_sk WHERE cd_closed.d_date IS NULL OR d_sold.d_date <= cd_closed.d_date GROUP BY c.c_customer_sk, c.c_first_name, c.c_last_name, s.s_store_sk, s.s_store_name, d_sold.d_year ) SELECT cs.c_customer_sk, cs.c_first_name, cs.c_last_name, cs.s_store_name, cs.sales_year, cs.total_profit, CASE WHEN cs.total_profit >= 50000 THEN 'Platinum' WHEN cs.total_profit >= 20000 THEN 'Gold' WHEN cs.total_profit >= 10000 THEN 'Silver' ELSE 'Bronze' END AS profit_tier, RANK() OVER (PARTITION BY cs.sales_year ORDER BY cs.total_profit DESC) AS profit_rank_year, DENSE_RANK() OVER (ORDER BY cs.total_profit DESC) AS global_profit_dense_rank FROM cust_store_year cs ORDER BY cs.sales_year DESC, cs.total_profit DESC LIMIT 30
